const tabCases = () => TABLEAUX[game.questions[game.index].t];
const motT = (i) => { const c = tabCases()[i]; const x = c.t.replace(/[.,!?]$/, ''); return c.nat === 'NP' ? x : x.toLowerCase(); };
const infT = (i) => tabCases()[i].inf || motT(i);
