const NAT_LIB = { VINF: 'Verbe à l\'infinitif', A: 'Adjectif qualificatif', Av: 'Adverbe', P: 'Préposition', CC: 'Conjonction de coordination', CS: 'Conjonction de subordination', I: 'Interjection' };
