  tadjq: () => ({ vert: true, texte: `Dans ce groupe nominal, le nom « ${motT(tabState.noms[tabState.ni])} » est-il décrit par un adjectif qualificatif épithète ou apposé ?`, choix: ['oui', 'non'] }),
