const TROUVE_CE = {"ce-noms": [{"titre": "Au salon", "texte": "Le {chat} de {Léa} dort sur le {canapé} . Le {chien} joue dans le {jardin} . {Papa} lit le {journal} . {Maman} prépare une {tarte} . La {pluie} tombe."}, {"titre": "En classe", "texte": "Ce {matin} , la {maîtresse} raconte une {histoire} . Les {élèves} écoutent. {Tom} dessine un {dragon} sur son {cahier} . {Lina} colorie une {princesse} . La {cloche} sonne. Les {enfants} sortent dans la {cour} . Ils jouent au {ballon} ."}, {"titre": "À la ferme", "texte": "{Dimanche} , {mamie} et {papi} nous emmènent à la {ferme} . Le {fermier} nous montre ses {vaches} et ses {cochons} . Mon {frère} caresse un {agneau} . Ma {sœur} ramasse des {œufs} dans le {poulailler} . Nous buvons du {lait} frais. Le {chien} {Pirate} court après les {poules} ."}, {"titre": "À la mer", "texte": "Pendant les {vacances} , nous partons à la {mer} avec nos {cousins} . {Paul} construit un {château} de {sable} avec des {tours} et un {pont} . {Juliette} cherche des {coquillages} sur la {plage} . {Maman} lit un {livre} sous le {parasol} . {Papa} nage jusqu'à la {bouée} . Le {soleil} brille. Les {mouettes} crient au-dessus des {vagues} . Notre {chien} aboie."}], "ce-dets": [{"titre": "Des petites phrases", "texte": "{Le} chat dort. {La} souris danse. {Un} oiseau chante. {Une} fleur s'ouvre. {Les} enfants rient. {Des} nuages passent. {Le} soleil brille. {La} lune se cache. {Un} chien aboie. {Une} cloche sonne."}, {"titre": "Dans la rue", "texte": "{Mon} frère a {un} vélo rouge. {Ma} sœur préfère {sa} trottinette. {Les} voisins promènent {leur} chien. {Ce} chien porte {un} collier bleu. {Mes} amis jouent dans {la} rue. {Cette} rue est calme. {Nos} parents nous regardent par {la} fenêtre."}, {"titre": "Les graines", "texte": "{Ce} matin, {la} maîtresse apporte {une} boîte. Dans {cette} boîte, il y a {des} graines. {Les} élèves plantent {les} graines dans {des} pots. {Mon} voisin arrose {son} pot. {Ta} plante pousse vite. {Ces} feuilles sont vertes. {Notre} classe ressemble à {un} jardin. {Les} parents viendront voir {nos} plantes."}, {"titre": "Les histoires de grand-père", "texte": "{Le} soir, {mon} grand-père raconte {des} histoires. {Ses} histoires parlent de {son} enfance. {Sa} maison était dans {un} village. {Les} enfants marchaient dans {la} neige. {Leurs} chaussures étaient mouillées. {Cette} époque était dure. {Ces} enfants avaient {des} sabots. {Leur} maîtresse chauffait {la} classe avec {un} poêle. {Ma} sœur et moi écoutons {ces} récits. {Notre} chat dort sur {mes} genoux."}], "ce-adjs": [{"titre": "Des couleurs", "texte": "Le {petit} chat dort sur un coussin {rouge} . Une {grande} girafe mange des feuilles {vertes} . Le ciel est {bleu} . Mon {vieux} chien est {gentil} . Ma sœur porte une robe {jaune} . Elle a des cheveux {longs} et {bruns} ."}, {"titre": "Le loup et la chouette", "texte": "Dans la forêt {sombre} , un {jeune} loup cherche son chemin. Il a un pelage {gris} et des yeux {jaunes} . Il entend un bruit {étrange} . C'est une {vieille} chouette {blanche} . Elle est {sage} et {gentille} . Elle montre au loup un sentier {étroit} . Le loup est {content} . Il rentre dans sa {belle} tanière. Il est {fatigué} ."}, {"titre": "Le jardin de mamie", "texte": "Mamie a un jardin {magnifique} . Elle cultive des tomates {rouges} , des salades {fraîches} et des {grosses} courges {orange} . Ses roses {parfumées} attirent des abeilles {dorées} . Au fond, il y a un {vieux} puits {mystérieux} . Le chat {roux} de mamie dort sur le mur {tiède} . Les oiseaux {joyeux} chantent dans le {grand} cerisier. Mamie est {fière} de son jardin {fleuri} . C'est un endroit {paisible} ."}, {"titre": "Le petit prince", "texte": "Le {petit} prince habite un château {immense} . C'est un garçon {timide} . Les murs sont {épais} et les tours sont {hautes} . Dans la {grande} salle, il y a une table {longue} avec une nappe {blanche} . Le prince porte un manteau {rouge} et des bottes {noires} . Son cheval est {rapide} et {fougueux} . Un jour, le prince rencontre une fée {minuscule} . Elle a des ailes {transparentes} et une voix {douce} . Elle lui offre une épée {magique} . Le prince devient {courageux} . Il part pour un {long} voyage vers des pays {lointains} . Il est {heureux} ."}], "ce-prons": [{"titre": "Les amis", "texte": "{Je|s'appeler} m'appelle Lou. {Tu|s'appeler} t'appelles Tom. {Il|être} est mon voisin. {Elle|être} est ma sœur. {Nous|jouer} jouons ensemble. {Vous|venir} venez avec nous ? {Ils|courir} courent vite. {Elles|sauter} sautent à la corde. {On|rire} rit beaucoup. {Tu|être} es mon ami."}, {"titre": "La piscine", "texte": "Ce matin, {nous|aller} allons à la piscine. {Je|prendre} prends mon maillot. Maman dit : « {Tu|oublier} n'oublies pas ta serviette ? » Papa conduit. {Il|chanter} chante dans la voiture. Ma sœur rit. {Elle|trouver} trouve papa drôle. À la piscine, {nous|retrouver} retrouvons nos cousins. {Ils|nager} nagent déjà. « {Vous|être} êtes en retard ! » crie Léo. {On|se dépêcher} se dépêche. {Je|plonger} plonge. L'eau est froide ! {Elle|faire} me fait frissonner. {Il|falloir} faut nager vite. {Nous|sortir} sortons à midi."}, {"titre": "La fête de la classe", "texte": "Les enfants préparent une fête. {Ils|décorer} décorent la classe. Léa et Zoé gonflent des ballons. {Elles|accrocher} les accrochent au plafond. Tom apporte un gâteau. {Il|faire} l'a fait avec sa maman. « {Je|pouvoir} peux le goûter ? » demande Hugo. « {Tu|attendre} attendras la fête ! » répond Tom. La maîtresse arrive. {Elle|sourire} sourit. {Elle|mettre} met de la musique. « {Vous|travailler} avez bien travaillé ! {Je|être} suis fière de vous. » {Nous|chanter} chantons une chanson. {On|danser} danse aussi. {Je|danser} danse avec Léa. « {Tu|danser} danses bien ! » dit Zoé. Les parents arrivent. {Ils|applaudir} applaudissent. {Nous|manger} mangeons le gâteau. {Il|être} est délicieux !"}, {"titre": "Au cirque", "texte": "Hier, {nous|aller} sommes allés au cirque. {Je|s'asseoir} me suis assis au premier rang. Mon père s'est assis à côté de moi. {Il|acheter} avait acheté des bonbons. {Nous|attendre} avons attendu un peu. Puis les clowns sont arrivés. {Ils|porter} portaient des chaussures géantes. {Ils|tomber} sont tombés plusieurs fois. {On|rire} a beaucoup ri. Ensuite, une acrobate est entrée. {Elle|monter} est montée sur un fil. {Elle|marcher} a marché sans tomber. « {Vous|avoir} avez peur ? » nous a demandé le présentateur. « {Nous|avoir} avons un peu peur ! » a répondu ma sœur. Les lions ont rugi. {Ils|être} étaient impressionnants. Ma sœur a fermé les yeux. {Je|dire} lui ai dit : « {Tu|pouvoir} peux regarder ! {Ils|être} sont dans une cage. » {Elle|ouvrir} a ouvert les yeux. À la fin, {nous|applaudir} avons applaudi. {Nous|rentrer} sommes rentrés tard. {Je|dormir} dormais dans la voiture. {Il|faire} faisait nuit."}], "ce-sujets": [{"titre": "Petites phrases", "texte": "Le {chat|dormir} dort. Les {oiseaux|chanter} chantent. {Maman|cuisiner|np} cuisine. Mon {frère|jouer} joue. Le {soleil|briller} brille. {Tu|lire} lis un livre. Les {enfants|courir} courent dans la cour. {Papa|réparer|np} répare le vélo. La {pluie|tomber} tombe. {Nous|rentrer} rentrons à la maison."}, {"titre": "En classe", "texte": "La {maîtresse|écrire} écrit au tableau. Les {élèves|recopier} recopient la leçon. {Léo|lever|np} lève le doigt. {Il|poser} pose une question. Sa {voisine|répondre} répond. Le {directeur|entrer} entre dans la classe. Toute la {classe|se lever} se lève. {Il|saluer} salue les élèves. La {cloche|sonner} sonne. Les {enfants|sortir} sortent. {Tom|attendre|np} m'attend. {Nous|jouer} jouons aux billes. La {récréation|passer} passe vite."}, {"titre": "À la plage", "texte": "Le petit {chien|aboyer} de Léa aboie. Les grandes {vagues|frapper} frappent les rochers. Dans le ciel volent des {mouettes|voler} . Mes {cousins|construire} construisent un château. Le {vent|souffler} souffle fort. Ma {sœur|chercher} et {moi|chercher} cherchons des coquillages. {Papa|lire|np} lit sous le parasol. Sur la plage courent des {enfants|courir} . Le {marchand|passer} de glaces passe. {Il|crier} crie : « Glaces ! » {Maman|acheter|np} achète trois glaces. {Nous|manger} les mangeons vite. Le {soleil|chauffer} chauffe le sable. Les {nuages|arriver} arrivent. Un {orage|approcher} approche. {Nous|rentrer} rentrons."}, {"titre": "Le jardin de grand-père", "texte": "Chaque matin, mon {grand-père|se lever} se lève tôt. {Il|boire} boit son café. Puis {il|partir} part au jardin. Dans le potager poussent des {salades|pousser} . Les {tomates|rougir} rougissent au soleil. Les {limaces|manger} , la nuit, mangent les feuilles. {Grand-père|chasser|np} les chasse. Ma {grand-mère|cueillir} cueille des fraises. {Elle|faire} en fait de la confiture. Le {chat|se promener} de la voisine se promène. {Il|sauter} saute sur le mur. Sur le mur dorment des {lézards|dormir} . {Ils|s'enfuir} s'enfuient. Le {chien|aboyer} aboie. « {Tu|aller} vas te taire ! » crie {grand-mère|crier|np} . Les {oiseaux|s'envoler} s'envolent. {Nous|arriver} arrivons pour le déjeuner. Toute la {famille|se mettre} se met à table. {On|manger} mange la salade du jardin."}]};
const TROUVE_PH = {"ce-paroles": [{"titre": "Le ballon", "texte": "Léo voit un ballon dans l'arbre. {« Oh, mon ballon ! »} crie-t-il. Sa sœur arrive. {« Je vais t'aider »} , dit-elle. Elle prend une branche. {« Attention ! »} dit Léo. Le ballon tombe. {« Merci ! »} dit Léo. {« De rien »} , répond sa sœur. Ils rient. {« On joue ensemble ? »} demande Léo. {« D'accord ! »} Ils jouent jusqu'au soir. {« À table ! »} appelle maman. {« On arrive ! »} crient les enfants. {« Lavez-vous les mains »} , dit papa."}, {"titre": "Le marchand de glaces", "texte": "Le marchand de glaces arrive sur la plage. {« Glaces ! Glaces ! »} crie-t-il. Lina court vers lui. {« Bonjour, monsieur ! »} dit-elle. {« Bonjour ! Quel parfum veux-tu ? »} demande le marchand. {« Fraise, s'il vous plaît. »} Le marchand sert la glace. {« Voilà ! »} Lina donne une pièce. {« Merci beaucoup ! »} Son frère arrive en courant. {« Et moi ? »} demande-t-il. {« Tu veux quel parfum ? »} dit le marchand. {« Chocolat ! »} Lina sourit. {« Tu es gourmand ! »} dit-elle. {« Toi aussi ! »} répond son frère. Ils mangent leurs glaces au soleil. {« C'est délicieux ! »} dit Lina. {« J'en veux encore une ! »} réclame son frère."}, {"titre": "La petite poule", "texte": "La petite poule rousse trouve des grains de blé. {« Qui va m'aider à semer ce blé ? »} demande-t-elle. {« Pas moi »} , dit le chat. {« Pas moi »} , dit le chien. {« Pas moi »} , dit le canard. {« Alors je le sèmerai toute seule »} , dit la petite poule. Le blé pousse. {« Qui va m'aider à couper le blé ? »} {« Pas moi ! »} répondent les trois amis. La poule coupe le blé. Elle fait de la farine, puis un pain. {« Qui va m'aider à manger ce pain ? »} demande-t-elle. {« Moi ! »} dit le chat. {« Moi ! »} dit le chien. {« Moi aussi ! »} dit le canard. {« Non ! »} dit la poule. {« Je le mangerai avec mes poussins. »} Et elle le mange. Le chat soupire : {« La prochaine fois, je t'aiderai. »} {« Moi aussi »} , dit le chien. {« Et moi aussi ! »} promet le canard."}, {"titre": "Le loup et le chevreau", "texte": "Un petit chevreau reste seul dans la maison. Sa mère lui dit : {« N'ouvre à personne ! »} {« Promis, maman »} , répond le chevreau. Un peu plus tard, on frappe à la porte. {« Ouvre, c'est ta maman ! »} dit une grosse voix. {« Ma maman a une voix douce »} , dit le chevreau. {« Montre-moi ta patte. »} Le loup montre sa patte noire. {« Ma maman a une patte blanche ! »} crie le chevreau. {« Je n'ouvrirai pas ! »} Le loup est furieux. {« Je reviendrai ! »} grogne-t-il. Il s'en va. La mère rentre. {« C'est moi, mon petit. »} {« Montre ta patte »} , dit le chevreau. {« Voilà ma patte blanche. »} Le chevreau ouvre la porte. {« Le loup est venu ! »} dit-il. {« Tu as été très sage »} , répond sa mère. {« Je suis fière de toi. »} Le chevreau se blottit contre elle. {« J'ai eu peur »} , murmure-t-il. {« C'est fini »} , dit sa mère. {« Maintenant, nous allons manger. »} {« Qu'est-ce qu'il y a ? »} demande le chevreau. {« Une bonne soupe aux choux ! »} {« Miam ! »}"}], "ce-ccp": [{"titre": "Le matin", "texte": "Ce {matin|nc} , je me lève {tôt|adv} . Dans la {cuisine|nc} , maman prépare le petit-déjeuner. Je mange {vite|adv} . À huit {heures|nc} , nous partons. Dans la {rue|nc} , il fait froid. Devant la {porte|nc} de l'école, je retrouve Tom. {Ensemble|adv} , nous entrons dans la {cour|nc} . La cloche sonne {bientôt|adv} ."}, {"titre": "Le pique-nique", "texte": "{Dimanche|nc} , nous allons pique-niquer au {bord|nc} du lac. Sous un grand {arbre|nc} , papa étale la nappe. Avec {soin|nc} , maman sort les sandwichs. Nous mangeons {lentement|adv} . Après le {repas|nc} , mon frère joue dans le {pré|nc} . Sur le {lac|nc} , des canards nagent. Je leur donne du pain {doucement|adv} . Le {soir|nc} , nous rentrons à la {maison|nc} . Dans la {voiture|nc} , ma sœur s'endort. Nous chantons tout {bas|adv} ."}, {"titre": "L'hiver", "texte": "En {hiver|nc} , la neige tombe sur le {village|nc} . Le {matin|nc} , les enfants sortent {vite|adv} . Dans le {jardin|nc} , ils font un bonhomme de neige. Avec deux {cailloux|nc} , ils lui font des yeux. Pendant ce {temps|nc} , papa déblaie l'allée avec une {pelle|nc} . Sur le {lac|nc} gelé, des enfants patinent. Ils glissent très {vite|adv} . {Soudain|adv} , Lina tombe. Elle se relève {aussitôt|adv} . À {midi|nc} , tout le monde rentre. Près de la {cheminée|nc} , nous buvons un chocolat chaud. {Dehors|adv} , la neige tombe {encore|adv} ."}, {"titre": "Le voyage en train", "texte": "{Samedi|nc} , nous partons en {train|nc} . À la {gare|nc} , il y a beaucoup de monde. Nous montons {rapidement|adv} dans le wagon. Par la {fenêtre|nc} , je regarde le paysage. {D'abord|locadv} , nous voyons des champs. {Puis|adv} , le train traverse une forêt. Dans le {wagon|nc} , un bébé pleure. Sa maman le berce {doucement|adv} . Vers {midi|nc} , nous mangeons nos sandwichs. Sur la {tablette|nc} , je pose mon jus de pomme. {Tout à coup|locadv} , le train entre dans un tunnel. Dans le {noir|nc} , ma sœur crie. Quelques {secondes|nc} plus tard, la lumière revient. {Enfin|adv} , nous arrivons à {Marseille|np} . Sur le {quai|nc} , mamie nous attend avec un grand {sourire|nc} . Le {soir|nc} , nous mangeons chez {elle|pp} ."}]};
Object.assign(TROUVE_PH, {"cm-sujet": [{"titre": "La forêt en automne", "texte": "Dans la forêt, {les feuilles des chênes} tombent. {Les écureuils} ramassent des noisettes. Au loin résonne {le cri d'un geai} . {Mon frère et moi} marchons sur le tapis de feuilles. {Le vent} souffle doucement. {Un champignon énorme} pousse au pied d'un arbre. {Nous} le photographions. Sous une souche se cache {un hérisson} . {Il} dort. {L'automne} est magnifique."}, {"titre": "Le carnaval", "texte": "{Le carnaval de la ville} commence aujourd'hui. Dans les rues défilent {des chars décorés} . {Les enfants de l'école} portent des costumes. {Ma sœur et ses amies} sont déguisées en fées. Sur le premier char danse {un dragon de papier} . {La musique des fanfares} résonne. {Les spectateurs} applaudissent. {Ils} lancent des confettis. Soudain apparaît {le roi du carnaval} . {Tout le monde} crie de joie. {Les clowns} distribuent des bonbons. Moi, {je} ramasse les confettis. {La fête} durera jusqu'au soir."}, {"titre": "Les abeilles", "texte": "{Les abeilles} vivent en colonies. Dans chaque ruche règne {une reine} . {Elle} pond des milliers d'œufs. {Les ouvrières} , infatigables, butinent les fleurs. {Le nectar qu'elles rapportent} devient du miel. {L'apiculteur} , vêtu d'une combinaison, ouvre la ruche. {Ses gestes lents} rassurent les insectes. Du cadre sortent {quelques abeilles} . {Le miel doré} coule. {Mon oncle et moi} goûtons ce miel. {Il} est délicieux. Au printemps naissent {de nouvelles reines} . {L'une d'elles} quitte la ruche. {Une partie des ouvrières} la suit. {Ce départ} s'appelle l'essaimage. {Les abeilles} sont précieuses."}, {"titre": "Le premier vol", "texte": "Le 25 juillet 1909, {Louis Blériot} décolle de Calais. {Son avion} , un fragile monoplan, s'élève au-dessus de la mer. Sous lui s'étend {la Manche} . {Le brouillard} le gêne. {Aucun bateau} ne l'accompagne. {Le moteur} chauffe. Pendant de longues minutes, {l'aviateur} ne voit plus la côte. Puis apparaissent {les falaises de Douvres} . {Blériot} cherche un endroit pour atterrir. {Un policier anglais} lui fait signe. {L'avion} se pose brutalement. {Ses roues} se brisent. {Le pilote} sort indemne. {Les journaux du monde entier} racontent l'exploit. {Il} devient célèbre. À Paris l'attendent {des milliers de personnes} . {Son avion} est aujourd'hui exposé au musée. {Les enfants} l'admirent. {Chacun} rêve de voler. {Cette traversée} a changé l'histoire de l'aviation."}]});
Object.assign(TROUVE_PH, {"cm-paroles": [{"titre": "Au téléphone", "texte": "Le téléphone sonne. Léa décroche. {— Allô ?} {— Bonjour, c'est mamie !} {— Bonjour, mamie ! Comment vas-tu ?} {— Très bien. Tu viens dimanche ?} {— Oui, avec papa.} {— Parfait. Je ferai une tarte.} {— Aux pommes ?} {— Bien sûr !} {— Merci, mamie. À dimanche !} {— À dimanche, ma chérie.} Léa raccroche en souriant."}, {"titre": "Le marchand de ballons", "texte": "Un marchand de ballons arrive dans le parc. {— Ballons ! Beaux ballons !} crie-t-il. Hugo tire sa mère par la manche. {— Maman, je peux en avoir un ?} {— Lequel veux-tu ?} demande-t-elle. {— Le rouge, celui qui a des étoiles !} Le marchand détache le ballon. {— Tiens-le bien, mon garçon} , dit-il. {— Combien vous dois-je ?} demande la maman. {— Deux euros, madame.} Elle paie. Hugo s'éloigne en courant. Soudain, le vent souffle. {— Mon ballon !} s'écrie-t-il. Le ballon s'envole au-dessus des arbres. Le marchand rit. {— Reviens, je t'en donne un autre !} {— Merci, monsieur !} {— Cette fois, attache-le à ton poignet.} {— Promis !} répond Hugo. {— Et ne lâche pas ta maman non plus !} ajoute le marchand en riant."}, {"titre": "La rencontre", "texte": "Sur le chemin de l'école, Malik rencontre un nouveau voisin. {— Salut ! Tu es nouveau ?} demande Malik. {— Oui, je m'appelle Théo. Nous sommes arrivés hier.} {— D'où viens-tu ?} {— De Marseille.} {— C'est loin ! Tu vas à l'école Jean-Moulin ?} {— Oui, en CM2.} {— Moi aussi !} s'exclame Malik. Les deux garçons marchent ensemble. {— Tu aimes le football ?} demande Théo. {— J'adore ça ! Je joue dans l'équipe du quartier.} {— Je peux venir ?} {— Bien sûr ! L'entraînement a lieu mercredi.} Devant l'école, la maîtresse les accueille. {— Bonjour, les garçons. Vous vous connaissez déjà ?} {— Depuis cinq minutes !} répond Malik en riant. La maîtresse sourit. {— Alors, vous serez voisins de table.} {— D'accord !} disent les garçons en chœur. {— On commence quand ?} demande Théo."}, {"titre": "Le trésor du pirate", "texte": "Le capitaine déplie la carte sur la table. {— Messieurs, voici la carte du trésor de Barbe-Grise.} Les pirates s'approchent. {— Où est-il caché ?} demande le second. {— Sur l'île du Crâne, au pied du grand palmier} , répond le capitaine. {— Cette île est maudite !} s'écrie un vieux marin. {— Balivernes !} grogne le capitaine. {— On dit que des serpents géants la gardent} , murmure le mousse. {— As-tu peur, petit ?} {— Un peu, capitaine.} {— Tu resteras sur le navire, alors.} Le mousse rougit. {— Non ! Je viens avec vous.} Les pirates éclatent de rire. {— Il a du courage, ce gamin !} dit le second. {— Préparez la chaloupe} , ordonne le capitaine. {— Nous partirons à l'aube.} {— Et si nous trouvons le trésor ?} demande le cuisinier. {— Chacun aura sa part.} {— Vive le capitaine !} crient les pirates. Le lendemain, la chaloupe s'éloigne vers l'île. {— Ramez plus vite !} hurle le capitaine. Une heure plus tard, la vigie s'écrie : {— Terre !} Le mousse sourit. {— Le trésor est à nous !} {— Pas encore, petit} , dit le capitaine."}]});
Object.assign(TROUVE_PH, {"c65-sujet": [{"titre": "Le concert", "texte": "Ce soir, {la chorale du collège} chante à l'église. {Les parents} sont nombreux. Dans la nef résonnent {les premières notes} . {Le chef de chœur} lève les bras. {Chanter devant un public} impressionne les élèves. {Ma sœur, qui a un solo,} tremble un peu. {Elle} respire profondément. {Sa voix} s'élève. {Tout le monde} se tait. {Le concert} est un succès."}, {"titre": "La forêt", "texte": "{La forêt de Brocéliande} cache bien des secrets. Sous les arbres coule {une source} . {Les promeneurs qui s'y aventurent} entendent des bruits étranges. {Merlin} y aurait vécu. {Les légendes} le racontent. {Se perdre dans cette forêt} est facile. {Le guide qui nous accompagne} connaît chaque sentier. {Il} nous montre le tombeau de l'enchanteur. Près de là dort {un lac mystérieux} . {Mes amis et moi} écoutons. {Nous} frissonnons. {La nuit} tombe. {Qui} oserait rester ?"}, {"titre": "Le collège", "texte": "{Le collège} ouvre ses portes à huit heures. {Les élèves de sixième} découvrent leur emploi du temps. {Changer de salle à chaque heure} les surprend. {Chaque professeur} a sa propre salle. C'est moi {qui} porte le plan du collège. Dans le couloir se pressent {des centaines d'élèves} . {Le bruit} est assourdissant. {Ma meilleure amie et moi} cherchons la salle de sciences. {Un surveillant, qui nous voit perdues,} nous aide. {Il} nous accompagne. {Le cours} a déjà commencé. {La professeure} sourit. {Les retardataires} s'assoient. {Apprendre} devient passionnant. {Cette première journée} restera un bon souvenir. {Nos parents} nous attendent à la sortie."}, {"titre": "Le tremblement de terre", "texte": "Le 1er novembre 1755, {Lisbonne} fut détruite par un tremblement de terre. Ce matin-là, {les habitants} assistaient à la messe. Soudain, {le sol} se mit à trembler. {Les églises} s'effondrèrent. {Des milliers de personnes} périrent sous les ruines. Puis arriva {un immense raz-de-marée} . {Les survivants qui s'étaient réfugiés sur les quais} furent emportés. {Des incendies} ravagèrent la ville pendant six jours. {Reconstruire Lisbonne} prit des années. {Le marquis de Pombal, ministre du roi,} dirigea les travaux. {Il} fit tracer de larges avenues. {Les nouveaux bâtiments} résistaient mieux aux secousses. {Toute l'Europe} fut bouleversée. {Voltaire} écrivit un poème sur la catastrophe. Dans les salons parisiens naquit {un grand débat} . {Les philosophes} s'interrogeaient. Pourquoi {Dieu} permettait-il cela ? {Cette question} hanta les esprits. {La science des séismes} venait de naître. {Les savants} étudièrent la catastrophe."}]});
const TROUVE = { 'ce-verbe': TEXTES_TV, ...TROUVE_CE, ...TROUVE_PH };
/* v74 : ce que dit le panneau, pour chaque exercice où l'on touche des mots */
const PAS_SUJET = /^(me|te|se|le|la|les|lui|leur|nous|vous|moi|toi|eux|l'|m'|t'|s')$/i;
const TVCFG = {
  'ce-verbe': { instr: 'Trouve les verbes conjugués', u: ['verbe conjugué', 'verbes conjugués'], m: true, carte: 'Touche dans le texte tous les <strong>verbes conjugués</strong>.', aide: 'Un verbe conjugué change quand on change le moment : <em>aujourd\'hui il court, hier il courait, demain il courra</em>. Attention : un verbe à l\'<strong>infinitif</strong> (<em>nager, pêcher</em>) n\'est pas conjugué. Au passé composé, le verbe a deux mots (<em>a fermé</em>) : touche-le une seule fois.', ok: 'Oui, c\'est un verbe conjugué !',
    non: (w) => `Non : « ${esc(w)} » n'est pas un verbe conjugué${/(er|ir|re)$/.test(w) && w.length > 3 ? ' (si c\'est un verbe, il est à l\'infinitif)' : ''}`,
    fin: 'Pour trouver le <strong>verbe conjugué</strong>, change le moment de la phrase : le mot qui change, c\'est le verbe (<em>il court → hier il courait → demain il courra</em>). On peut aussi l\'encadrer avec « ne… pas » : <em>il ne court pas</em>. L\'<strong>infinitif</strong> (<em>nager, pêcher</em>) est le nom du verbe : il n\'est pas conjugué.' },
  'ce-noms': { instr: 'Trouve les noms communs et les noms propres', u: ['nom', 'noms'], m: true, carte: 'Touche dans le texte tous les <strong>noms communs</strong> et tous les <strong>noms propres</strong>.', aide: 'Un nom désigne une personne, un animal, une chose ou une idée : on peut mettre devant lui <em>le, la, un, une</em> (<em>la pluie, un dragon</em>). Les <strong>noms propres</strong> (<em>Léa, Paris</em>) commencent par une majuscule : ce sont aussi des noms.', ok: (w) => (/^(Léa|Tom|Lina|Pirate|Paul|Juliette)$/.test(w) ? `Oui, « ${esc(w)} » est un nom propre !` : `Oui, « ${esc(w)} » est un nom commun !`),
    non: (w) => `Non : « ${esc(w)} » n'est ni un nom commun, ni un nom propre${/^(le|la|les|un|une|des|mon|ma|mes|ton|ta|tes|son|sa|ses|ce|cette|ces|nos|notre|leur|leurs)$/i.test(w) ? ' : c\'est le petit mot qui l\'annonce, le déterminant' : ''}`,
    fin: 'Le <strong>nom</strong> désigne une personne, un animal, une chose ou une idée. Pour le reconnaître, on essaie de mettre <em>le, la, un</em> ou <em>une</em> devant lui. Les <strong>noms propres</strong> (prénoms, noms de villes, de pays, d\'animaux familiers) commencent par une majuscule.' },
  'ce-dets': { instr: 'Trouve les déterminants', u: ['déterminant', 'déterminants'], m: true, carte: 'Touche dans le texte tous les <strong>déterminants</strong>.', aide: 'Le déterminant est le petit mot placé <strong>devant le nom</strong> : <em>le, la, les, un, une, des, mon, ta, ses, leur, ce, cette, ces…</em> Il annonce le nom et dit s\'il est masculin ou féminin, singulier ou pluriel.', ok: 'Oui, c\'est un déterminant !',
    non: (w) => `Non : « ${esc(w)} » n'est pas un déterminant`,
    fin: 'Le <strong>déterminant</strong> est le petit mot qui se place <strong>devant le nom</strong> pour l\'annoncer : les articles (<em>le, la, les, un, une, des</em>), les possessifs (<em>mon, ta, ses, leur…</em>), les démonstratifs (<em>ce, cette, ces</em>). Il porte le genre et le nombre du nom.' },
  'ce-adjs': { instr: 'Trouve les adjectifs qualificatifs', u: ['adjectif qualificatif', 'adjectifs qualificatifs'], m: true, carte: 'Touche dans le texte tous les <strong>adjectifs qualificatifs</strong>.', aide: 'L\'adjectif dit <strong>comment est</strong> le nom : sa couleur, sa taille, son caractère… Il est à côté du nom (<em>un chat <strong>noir</strong>, une <strong>petite</strong> souris</em>) ou après le verbe <em>être</em> (<em>le ciel est <strong>bleu</strong></em>). Il s\'accorde avec le nom.', ok: 'Oui, c\'est un adjectif !',
    non: (w) => `Non : « ${esc(w)} » n'est pas un adjectif`,
    fin: 'L\'<strong>adjectif</strong> dit <strong>comment est</strong> le nom. On peut l\'enlever sans que la phrase soit fausse (<em>un chat noir → un chat</em>), ou le mettre après <em>être</em> (<em>le chat est noir</em>). Il prend le genre et le nombre du nom : <em>des fleurs rouges</em>, <em>une grande girafe</em>.' },
  'ce-prons': { instr: 'Trouve les pronoms personnels qui ont la fonction sujet', u: ['pronom personnel sujet', 'pronoms personnels sujets'], m: true, carte: 'Touche dans le texte tous les <strong>pronoms personnels</strong> ayant la <strong>fonction sujet</strong>.', aide: 'Les pronoms personnels sujets : <em>je, tu, il, elle, on, nous, vous, ils, elles</em>. Ils remplacent celui qui fait l\'action. Un pronom qui n\'est pas sujet (<em>il <strong>me</strong> regarde, je <strong>le</strong> vois</em>) ne compte pas.', ok: 'Oui, c\'est un pronom sujet !',
    non: (w) => PAS_SUJET.test(w) ? `« ${esc(w)} » est bien un pronom, mais ici il n'est pas sujet : ce n'est pas lui qui fait l'action` : `Non : « ${esc(w)} » n'est pas un pronom personnel sujet`,
    fin: 'Les <strong>pronoms personnels sujets</strong> sont <em>je, tu, il, elle, on, nous, vous, ils, elles</em>. Ils se placent en général <strong>devant le verbe</strong> et disent <strong>qui fait l\'action</strong>. <em>Il</em> remplace un nom masculin, <em>elle</em> un nom féminin, <em>ils</em> et <em>elles</em> des noms au pluriel.' },
  'ce-sujets': { instr: 'Trouve le sujet de chaque verbe', u: ['sujet', 'sujets'], m: true, carte: 'Touche le <strong>sujet</strong> de chaque verbe : un seul mot, le nom commun, le nom propre ou le pronom personnel.', aide: 'Pose la question « <strong>Qui est-ce qui</strong>… ? » devant le verbe : <em>Qui est-ce qui aboie ? Le petit chien de Léa</em> : le sujet, c\'est le nom commun <em>chien</em>. Parfois il est placé <strong>après</strong> le verbe (<em>Dans le ciel volent des mouettes</em>).', ok: 'Oui, c\'est le sujet du verbe !',
    non: (w) => `Non : « ${esc(w)} » n'est pas le sujet d'un verbe. Pose la question « Qui est-ce qui… ? »`,
    fin: 'Pour trouver le <strong>sujet</strong>, on pose la question « <strong>Qui est-ce qui</strong>… ? » (ou « <strong>Qu\'est-ce qui</strong>… ? ») devant le verbe. Le sujet commande l\'accord du verbe : <em>le chat dort, les chats dorment</em>. On peut l\'encadrer avec « <strong>c\'est… qui</strong> » : <em>c\'est le chat qui dort</em>.' },
};
Object.assign(TVCFG, {
  'ce-paroles': { instr: 'Trouve les paroles des personnages', u: ['parole', 'paroles'], carte: 'Touche toutes les <strong>paroles des personnages</strong>.', aide: 'Les paroles sont écrites <strong>entre guillemets</strong> « … ». Juste à côté, de petits mots disent qui parle (<em>dit Léo, demande-t-elle</em>) : ils font partie du récit, pas des paroles.', ok: 'Oui, ce sont des paroles d\'un personnage !',
    non: (w) => `Non : « ${esc(w)} » fait partie du récit, ce n'est pas une parole entre guillemets`,
    fin: 'Quand on écrit les paroles d\'un personnage telles qu\'il les a dites, on les met <strong>entre guillemets</strong> « … » : c\'est le <strong>discours direct</strong>. Un petit groupe de mots dit souvent qui parle et comment : <em>dit-il, demande-t-elle, crie Léo</em>. Dans un dialogue, chaque nouvelle réplique change de personnage.' },
  'ce-ccp': { instr: 'Trouve les compléments de phrase', u: ['complément', 'compléments'], carte: 'Touche le mot principal de chaque <strong>complément de phrase</strong> : un nom commun (<em>matin</em>) ou un adverbe (<em>vite</em>).', aide: 'Ils disent <strong>où</strong>, <strong>quand</strong> ou <strong>comment</strong> se passe l\'action. On peut les <strong>déplacer</strong> ou les <strong>supprimer</strong> : la phrase garde son sens. Dans <em>dans la cuisine</em>, touche seulement le nom commun <em>cuisine</em>.', ok: 'Oui, c\'est un complément de phrase !',
    non: (w) => `Non : « ${esc(w)} » ne fait pas partie d'un complément de phrase. Essaie de le déplacer ou de le supprimer`,
    fin: 'Les <strong>compléments de phrase</strong> disent <strong>où</strong> (<em>dans le jardin</em>), <strong>quand</strong> (<em>ce matin</em>) ou <strong>comment</strong> (<em>doucement</em>) se passe l\'action. On les reconnaît parce qu\'on peut les <strong>déplacer</strong> (<em>Ce matin, je me lève → Je me lève ce matin</em>) ou les <strong>supprimer</strong> (<em>Je me lève</em>). Placés en tête de phrase, ils sont souvent suivis d\'une virgule.' },
});
TVCFG['cm-paroles'] = { instr: 'Trouve les répliques du dialogue', u: ['réplique', 'répliques'], carte: 'Touche toutes les <strong>répliques</strong> des personnages.', aide: 'Dans un dialogue, chaque réplique commence par un <strong>tiret</strong> (—). Les petits groupes qui disent qui parle (<em>crie-t-il, demande Théo</em>) appartiennent au récit : ne les touche pas.', ok: 'Oui, c\'est une réplique !',
  non: (w) => `Non : « ${esc(w)} » fait partie du récit, pas des paroles d'un personnage`,
  fin: 'Dans un <strong>dialogue</strong>, chaque <strong>réplique</strong> commence par un tiret et va à la ligne dans les livres. Les incises (<em>dit-il, demande Théo, s\'écrie Malik</em>) disent qui parle et comment : elles font partie du récit. Le dialogue est une autre façon d\'écrire le <strong>discours direct</strong>, sans guillemets à chaque réplique.' };
TVCFG['c65-sujet'] = { ...TVCFG['ce-sujets'], carte: 'Touche le <strong>sujet</strong> de chaque verbe.', aide: 'Encadre avec « <strong>C\'est… qui</strong> » ou pose la question « Qui est-ce qui… ? ». Le sujet peut être un groupe nominal long (avec une proposition relative : <em>les promeneurs qui s\'y aventurent</em>), un pronom (<em>qui, il, nous</em>), un <strong>infinitif</strong> (<em>Chanter devant un public</em>), et il peut être placé <strong>après</strong> le verbe. Touche-le une seule fois.' };
TVCFG['cm-sujet'] = { ...TVCFG['ce-sujets'], carte: 'Touche le <strong>sujet</strong> de chaque verbe.', aide: 'Pose la question « <strong>Qui est-ce qui</strong>… ? » devant le verbe, ou encadre avec « <strong>C\'est… qui</strong> ». Le sujet peut être loin du verbe, placé <strong>après</strong> lui (<em>Dans la ruche règne une reine</em>), ou fait de plusieurs groupes (<em>Mon frère et moi</em>). Touche-le une seule fois.' };
const tv = { trouves: {}, cibles: 0 };
const TV_T = () => TROUVE[currentGame.tv][game.questions[game.index].t];
const TVC = () => TVCFG[currentGame.tv] || TVCFG['ce-verbe'];
function showQuestionTV() {
  const T = TV_T(); let n = 0;
  const mots = [];
  T.texte.replace(/\{([^}]+)\}|([^\s{]+)/g, (m, v, w) => {
    if (v !== undefined) { const [t0, inf, nat] = v.split('|'); mots.push({ t: t0, k: n++, inf, nat }); }   /* v111 : {chien|aboyer|nc} : le verbe dont il est sujet, sa nature */
    else if (/^[.,;:!?»]$/.test(w) && mots.length) mots[mots.length - 1].suf = (mots[mots.length - 1].suf || '') + (/^[;:!?»]$/.test(w) ? ' ' : '') + w;
    else mots.push({ t: w });
    return m;
  });
  Object.assign(tv, { trouves: {}, cibles: n });
  currentGame.total = n;
  $('nat-sentence').innerHTML = `<div class="tm-cadre"><h3 class="tm-titre">« ${esc(T.titre)} »</h3><div class="dr-texte tv-texte">${mots.map((m, i) => `<span class="dr-mot tv-mot" data-i="${i}"${m.k !== undefined ? ` data-k="${m.k}"` : ''}${m.inf ? ` data-inf="${esc(m.inf)}"` : ''}${m.nat ? ` data-nat="${m.nat}"` : ''}>${esc(m.t)}</span>${m.suf ? esc(m.suf) : ''}`).join(' ')}</div></div>`;
  $('nat-character-stage').innerHTML = '';
  $('nat-correction').classList.add('hidden');
  $('nat-verdict-square').className = 'verdict-square';
  $('nat-fn-column').classList.add('hidden'); $('nat-nature-column').classList.remove('hidden');
  $('nat-buttons-invariables').innerHTML = '';
  $('nat-progress-label').textContent = `Texte n° ${game.questions[game.index].t + 1} « ${T.titre} »`;
  game.score = 0;
  $('nat-sentence').onclick = (ev) => { const w = ev.target.closest('.tv-mot'); if (w && currentGame.tv && !game.fini) clicTV(w); };
  majTV(); panneauTV();
  requestAnimationFrame(ajusteArdoise);
}
function majTV() {
  $('nat-score-label').textContent = scoreLabel(Math.max(0, game.score));
  $('nat-progress-bar').style.width = `${(Object.keys(tv.trouves).length / tv.cibles) * 100}%`;
}
function panneauTV(message) {
  const C = TVC();
  $('nat-instruction').textContent = C.instr;
  const n = Object.keys(tv.trouves).length;
  $('nat-buttons-variables').innerHTML = nbspFr(`<div class="carte verte active libre"><p>${C.carte}</p><p class="sous">${C.aide}</p><p class="sous">${n} ${C.u[n > 1 ? 1 : 0]} sur ${tv.cibles} trouvé${n > 1 ? 's' : ''}.</p></div>${message ? `<p class="sous sx-aide">${message}</p>` : ''}`);
}
function clicTV(w) {
  if (w.dataset.k !== undefined) {
    if (tv.trouves[w.dataset.k]) return;
    tv.trouves[w.dataset.k] = true; w.classList.add('trouve-v');
    /* v111 : sous le mot trouvé, son étiquette : la nature en vert, la fonction en rouge (pas de commentaire dans l'encart) */
    const L = etiquettesTV(currentGame.tv, w.textContent, w.dataset.inf, w.dataset.nat);
    if (L.length) { w.innerHTML = `<span class="tv-tx">${esc(w.textContent)}</span><span class="tv-labs">${L.map(([t, rouge]) => `<span class="tv-lab${rouge === 'bleu' ? ' bleu' : rouge ? ' rouge' : ''}">${t}</span>`).join('')}</span>`; w.classList.add('tv-etiq'); }
    game.score = Math.round((game.score + 1) * 10) / 10; majTV();
    const reste = tv.cibles - Object.keys(tv.trouves).length;
    panneauTV(reste ? '' : '✔ Tu les as tous trouvés !');
    if (!reste) setTimeout(finTV, 1200);
    return;
  }
  game.score = Math.round((game.score - 0.5) * 10) / 10;
  game.erreurs.push({ mot: w.textContent, bonne: `pas un ${TVC().u[0]}`, choisie: TVC().u[0], phrase: `texte « ${TV_T().titre} »` });
  w.classList.add('dr-faux'); setTimeout(() => w.classList.remove('dr-faux'), 900);
  majTV();
  panneauTV(`${TVC().non(w.textContent)} (– 0,5 point).`);
}
/* v111 : les étiquettes des mots trouvés : [texte, rouge ?] — nature en vert, fonction en rouge */
const NAT_DET_TV = { le: 'article défini', la: 'article défini', "l'": 'article défini', les: 'article défini', un: 'article indéfini', une: 'article indéfini', des: 'article indéfini',
  du: 'article', au: 'article défini contracté', aux: 'article défini contracté',
  mon: 'déterminant possessif', ma: 'déterminant possessif', mes: 'déterminant possessif', ton: 'déterminant possessif', ta: 'déterminant possessif', tes: 'déterminant possessif', son: 'déterminant possessif', sa: 'déterminant possessif', ses: 'déterminant possessif', notre: 'déterminant possessif', nos: 'déterminant possessif', votre: 'déterminant possessif', vos: 'déterminant possessif', leur: 'déterminant possessif', leurs: 'déterminant possessif',
  ce: 'déterminant démonstratif', cet: 'déterminant démonstratif', cette: 'déterminant démonstratif', ces: 'déterminant démonstratif',
  deux: 'déterminant numéral', trois: 'déterminant numéral', quatre: 'déterminant numéral', cinq: 'déterminant numéral', six: 'déterminant numéral', sept: 'déterminant numéral', huit: 'déterminant numéral', neuf: 'déterminant numéral', dix: 'déterminant numéral', cent: 'déterminant numéral', mille: 'déterminant numéral',
  quelques: 'déterminant indéfini', plusieurs: 'déterminant indéfini', chaque: 'déterminant indéfini', tous: 'déterminant indéfini', toutes: 'déterminant indéfini', aucun: 'déterminant indéfini', aucune: 'déterminant indéfini' };
const PRON_PERS_TV = /^(je|j'|tu|il|elle|on|nous|vous|ils|elles|moi|toi|lui|eux)$/i;
function etiquettesTV(cle, mot, inf, nat) {
  const m = String(mot || '').trim(), l = m.toLowerCase().replace(/’/g, "'");
  const suj = inf ? `sujet du verbe ${inf}` : 'sujet';
  const natSuj = nat === 'np' ? 'nom propre' : nat === 'nc' ? 'nom commun' : PRON_PERS_TV.test(l) ? 'pronom personnel' : /^\p{Lu}/u.test(m) ? 'nom propre' : 'nom commun';
  if (cle === 'ce-noms') return [[/^\p{Lu}/u.test(m) ? 'nom propre' : 'nom commun']];
  if (cle === 'ce-dets') return [[NAT_DET_TV[l] || 'déterminant']];
  if (cle === 'ce-adjs') return [['adjectif qualificatif']];
  if (cle === 'ce-prons') return [['pronom personnel'], [suj, true]];
  if (cle === 'ce-verbe') return [['verbe conjugué']];
  if (cle === 'ce-sujets') return [[natSuj], [suj, true]];
  if (/sujet/.test(cle)) return [['sujet', true]];
  if (cle === 'ce-ccp') return [[{ nc: 'nom commun', np: 'nom propre', adv: 'adverbe', locadv: 'locution adverbiale', pp: 'pronom personnel' }[inf] || 'nom commun'], ['complément de phrase', true]];
  if (/paroles/.test(cle)) return [['discours direct', 'bleu']];
  return [];
}
function finTV() {
  boutonVoix(true);
  game.score = Math.max(0, game.score);
  $('nat-buttons-variables').innerHTML = '';
  $('nat-instruction').textContent = 'C\'est fini !';
  const total = currentGame.total;
  $('nat-correction-details').innerHTML = nbspFr(`Tu as ${fmtPts(game.score)} point${game.score >= 2 ? 's' : ''} sur ${total}. ${TVC().fin}`);
  $('nat-correction').classList.remove('hidden');
  $('nat-verdict-square').className = `verdict-square ${game.score >= total - 0.05 ? 'correct' : game.score < total / 2 ? 'wrong' : 'half'}`;
  $('nat-next-button').textContent = 'Voir mon résultat →';
  showCharacter(game.score >= total / 2 ? 'good' : 'bad', null);
}
