  const memesMots = (x) => { const a = nrm(x).split(/\s+/), b = n.split(/\s+/); return a.slice(0, 2).join(' ') === b.slice(0, 2).join(' ') && [...a].sort().join(' ') === [...b].sort().join(' '); };
