  ciblesSX().forEach((c) => { sx.cibles[c.cle] = { ...c, fait: false }; peintSX(c.lane, c.a, c.b, `vide ${COUL_SX[c.lane]}`, ''); marqueCibleSX(c); });
  currentGame.total = Object.keys(sx.cibles).length;
