  $('nat-buttons-invariables').innerHTML = '';
  $('nat-progress-label').textContent = `Texte n° ${game.questions[game.index].t + 1} « ${SX_T().titre} » (${NIVEAU_TEXTE(game.questions[game.index].t, listeTextes().length)})`;
